// Generate a weighted grid: terrain costs 1..5 plus impassable walls (0).
// Seeded PRNG so every run produces the same map.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const W = 48, H = 32;
const rand = mulberry32(20260709);

// Rolling-hills terrain: sum a few random bumps, quantise to cost 1..5.
const bumps = Array.from({ length: 24 }, () => ({
  x: rand() * W, y: rand() * H, r: 4 + rand() * 10, amp: rand(),
}));
const cost = new Array(W * H);
for (let y = 0; y < H; y++) {
  for (let x = 0; x < W; x++) {
    let v = 0;
    for (const b of bumps) {
      const d = Math.hypot(x - b.x, y - b.y);
      if (d < b.r) v += b.amp * (1 - d / b.r);
    }
    cost[y * W + x] = 1 + Math.min(4, Math.floor(v * 2.2));
  }
}

// Walls: random rectangles, kept away from start and goal corners.
let wallCells = 0;
for (let i = 0; i < 26; i++) {
  const rw = 1 + Math.floor(rand() * 4);
  const rh = 1 + Math.floor(rand() * 4);
  const rx = Math.floor(rand() * (W - rw));
  const ry = Math.floor(rand() * (H - rh));
  if (rx + rw > W - 6 && ry + rh > H - 6) continue; // keep goal corner open
  if (rx < 6 && ry < 6) continue;                   // keep start corner open
  for (let y = ry; y < ry + rh; y++)
    for (let x = rx; x < rx + rw; x++) {
      if (cost[y * W + x] !== 0) wallCells++;
      cost[y * W + x] = 0;
    }
}

nb.set('astar_grid', { w: W, h: H, cost, start: [1, 1], goal: [W - 2, H - 2] });
if (!nb.has('astar_weight')) nb.set('astar_weight', 1);
if (!nb.has('astar_diagonal')) nb.set('astar_diagonal', false);

console.log('grid ' + W + 'x' + H + ', ' + wallCells + ' wall cells, costs 1..5');
console.log('published as astar_grid - the map below updates automatically');

// A* at every weight from 0 to 3, the same search as the map above.
const grid = nb.get('astar_grid');
if (!grid) return 'Run the terrain cell first.';
const diagonal = !!nb.get('astar_diagonal');

function astar(weight) {
  const { w: W, h: H, cost } = grid;
  const [gx, gy] = grid.goal;
  const start = grid.start[1] * W + grid.start[0];
  const goal = gy * W + gx;
  const g = new Array(W * H).fill(Infinity);
  const closed = new Array(W * H).fill(false);
  const guess = (i) => {
    const dx = Math.abs((i % W) - gx), dy = Math.abs(((i / W) | 0) - gy);
    return diagonal ? Math.max(dx, dy) + 0.41421 * Math.min(dx, dy) : dx + dy;
  };
  const steps = [[1, 0], [-1, 0], [0, 1], [0, -1]]
    .concat(diagonal ? [[1, 1], [1, -1], [-1, 1], [-1, -1]] : []);

  g[start] = 0;
  const open = [[weight * guess(start), start]];
  let expanded = 0;
  while (open.length) {
    let best = 0;                               // smallest f; the first one wins a tie, as on the map
    for (let i = 1; i < open.length; i++) if (open[i][0] < open[best][0]) best = i;
    const cur = open.splice(best, 1)[0][1];
    if (closed[cur]) continue;
    closed[cur] = true;
    expanded++;
    if (cur === goal) break;
    const cx = cur % W, cy = (cur / W) | 0;
    for (const [dx, dy] of steps) {
      const nx = cx + dx, ny = cy + dy;
      if (nx < 0 || ny < 0 || nx >= W || ny >= H) continue;
      const ni = ny * W + nx;
      if (cost[ni] === 0 || closed[ni]) continue;
      const tentative = g[cur] + cost[ni] * (dx && dy ? 1.41421 : 1);
      if (tentative < g[ni]) {
        g[ni] = tentative;
        open.push([tentative + weight * guess(ni), ni]);
      }
    }
  }
  return { expanded, cost: g[goal] };
}

const rows = [];
for (let w = 0; w <= 3; w += 0.25) {
  const r = astar(w);
  rows.push({ weight: w, expanded: r.expanded, cost: Math.round(r.cost * 100) / 100 });
}
console.log('diagonal moves: ' + (diagonal ? 'on' : 'off'));
console.log('weight  expanded  route cost');
for (const r of rows) {
  console.log(r.weight.toFixed(2).padStart(6) + String(r.expanded).padStart(10) + r.cost.toFixed(2).padStart(12));
}

const line = { type: 'line', point: true, tooltip: true };
const x = { field: 'weight', type: 'quantitative', title: 'heuristic weight w' };
return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  data: { values: rows },
  vconcat: [
    { width: 760, height: 150, title: 'Squares expanded', mark: line,
      encoding: { x, y: { field: 'expanded', type: 'quantitative', title: 'squares' } } },
    { width: 760, height: 150, title: "The route's cost", mark: { ...line, color: '#f59e0b' },
      encoding: { x, y: { field: 'cost', type: 'quantitative', title: 'cost', scale: { zero: false } } } },
  ],
};
